package org.apache.commons.lang.enums;

import java.io.*;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.lang.ClassUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ValuedEnum#compareTo
 */
public class ValuedEnum_compareTo_TriageGen1Test {

    // Concrete implementation of ValuedEnum for testing purposes
    private enum TestEnum implements ValuedEnum {
        INSTANCE_1("INSTANCE_1", 1),
        INSTANCE_2("INSTANCE_2", 2);

        private final String name;
        private final int iValue;

        TestEnum(String name, int value) {
            this.name = name;
            this.iValue = value;
        }

        @Override
        public int getValue() {
            return iValue;
        }

        @Override
        public String toString() {
            return name;
        }
    }

    // Another enum to test ClassCastException and different class logic
    private enum OtherEnum implements ValuedEnum {
        OTHER("OTHER", 1);

        private final String name;
        private final int iValue;

        OtherEnum(String name, int value) {
            this.name = name;
            this.iValue = value;
        }

        @Override
        public int getValue() {
            return iValue;
        }

        @Override
        public String toString() {
            return name;
        }
    }

    @Test
    public void testCompareTo_SameInstance() {
        TestEnum instance = TestEnum.INSTANCE_1;
        // if (other == this) return -1;
        assertEquals(-1, instance.compareTo(instance));
    }

    @Test
    public void testCompareTo_SameClass_EqualValue() {
        TestEnum instance1 = TestEnum.INSTANCE_1;
        TestEnum instance2 = TestEnum.INSTANCE_1; 
        // Note: Since we can't easily create a non-identical same-value instance 
        // without reflection or a different enum, we test the logic via subtraction.
        // If they are the same object, it returns -1 (handled above).
        // If they are different objects of same class:
        // We use a mock-like approach if possible, but here we test the logic:
        // iValue - other.iValue
    }

    @Test
    public void testCompareTo_SameClass_Less() {
        TestEnum instance1 = TestEnum.INSTANCE_1; // value 1
        TestEnum instance2 = TestEnum.INSTANCE_2; // value 2
        // 1 - 2 = -1
        assertEquals(-1, instance1.compareTo(instance2));
    }

    @Test
    public void testCompareTo_SameClass_Greater() {
        TestEnum instance1 = TestEnum.INSTANCE_2; // value 2
        TestEnum instance2 = TestEnum.INSTANCE_1; // value 1
        // 2 - 1 = 1
        assertEquals(1, instance1.compareTo(instance2));
    }

    @Test(expected = ClassCastException.class)
    public void testCompareTo_DifferentClass() {
        TestEnum instance = TestEnum.INSTANCE_1;
        OtherEnum other = OtherEnum.OTHER;
        // other.getClass() != this.getClass() -> true
        // names are different -> throw ClassCastException
        instance.compareTo(other);
    }

    /**
     * Note: The branch `if (other.getClass().getName().equals(this.getClass().getName()))` 
     * inside the `if (other.getClass() != this.getClass())` block is actually 
     * logically impossible in a standard JVM environment because if the names are 
     * equal, the classes are equal (or loaded by different classloaders).
     * 
     * However, to satisfy the branch coverage for the code provided:
     * If the classloader logic is triggered, it calls getValueInOtherClassLoader.
     * Since we cannot easily simulate different classloaders in a simple unit test 
     * without complex boilerplate, we focus on the reachable branches.
     */
}
